import heapq

# TreeNode is provided by LeetCode: TreeNode(val, left, right)
def stabilizeBinaryTree(root):
    # Each subtree's cost-as-function-of-root-value is convex and piecewise linear.
    # Store it with "slope trick": left breakpoints (max-heap via negation) and
    # right breakpoints (min-heap), each with a lazy shift, plus the minimum value.
    class F:
        __slots__ = ("L", "R", "dl", "dr", "base")
        def __init__(self):
            self.L = []   # stores -(actual - dl)
            self.R = []   # stores  (actual - dr)
            self.dl = 0
            self.dr = 0
            self.base = 0

    def add_right_ramp(f, a):
        # add max(0, x - a)
        if f.L:
            top = -f.L[0] + f.dl
            if top > a:
                f.base += top - a
        heapq.heappush(f.L, -(a - f.dl))
        moved = -heapq.heappop(f.L) + f.dl
        heapq.heappush(f.R, moved - f.dr)

    def add_left_ramp(f, a):
        # add max(0, a - x)
        if f.R:
            top = f.R[0] + f.dr
            if a > top:
                f.base += a - top
        heapq.heappush(f.R, a - f.dr)
        moved = heapq.heappop(f.R) + f.dr
        heapq.heappush(f.L, -(moved - f.dl))

    def merge_into(big, small):
        # replay small's ramps one by one into big (small-to-large)
        big.base += small.base
        for v in small.L:
            add_left_ramp(big, -v + small.dl)
        for v in small.R:
            add_right_ramp(big, v + small.dr)

    # iterative post-order
    order = []
    stack = [root]
    while stack:
        node = stack.pop()
        order.append(node)
        if node.left: stack.append(node.left)
        if node.right: stack.append(node.right)

    func = {}
    for node in reversed(order):
        cur = None
        for child in (node.left, node.right):
            if child is None:
                continue
            g = func.pop(child)
            # relax: the child may differ from the parent by at most 1
            g.dl -= 1
            g.dr += 1
            if cur is None:
                cur = g
            else:
                if len(cur.L) + len(cur.R) < len(g.L) + len(g.R):
                    cur, g = g, cur
                merge_into(cur, g)
        if cur is None:
            cur = F()
        add_left_ramp(cur, node.val)
        add_right_ramp(cur, node.val)
        func[node] = cur
    return func[root].base
